import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Loading from '../../loading/Loading';
import './CompanyZapatos.css';
import CompanyMenu from '../Company_Menu/CompanyMenu';
import { getColores, setColores, getEmpresa, setEmpresa, getTallas, setTallas, getMarcas, setMarcas } from "../Company_Localstorang/Company_Localstorang";
import { Historial_Local } from '../../../Redux/Actions/Empresa/Actions-Empresa';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';
import { useNavigate } from 'react-router-dom';

const CompanyZapatos = () => {
    const [loading, setLoading] = useState(true);
    const dispatch = useDispatch();
    const navigator = useNavigate();
    const colores = useSelector((state) => state.COLORES);
    const Empresa = useSelector((state) => state.EMPRESA);
    const talla = useSelector((state) => state.TALLAS);
    const marca = useSelector((state) => state.MARCAS);

    const [formData, setFormData] = useState({
        name: '',
        color: '',
        talla: '',
        costo: '',
        marca: '',
        modelo: '',
        descripcion: '',
        calidad: '',
        url: ''
    });

    useEffect(() => {
        // Cargar datos del localStorage al montar el componente
        const storedColores = getColores() || [];
        const storedEmpresa = getEmpresa() || {};
        const storedTallas = getTallas() || [];
        const storedMarcas = getMarcas() || [];

        dispatch(Historial_Local(storedColores, storedTallas, storedMarcas, storedEmpresa));

        setLoading(false); // Marcar carga como completada
    }, [dispatch]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData({ ...formData, url: reader.result });
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log('Datos del zapato:', formData);
        // Aquí puedes enviar formData a tu backend o realizar otra acción
    };

    const hanldeAddMarca = () => {
        alertify.prompt(
            'Agregar Marca',
            'Ingrese el nombre de la nueva marca:',
            '',
            function (evt, value) {
                if (value.trim() !== '') {
                    setFormData({ ...formData, marca: value });
                    setMarcas([...marca, { id: marca.length + 1, marca: value }]);
                    alertify.alert('Mensaje', 'Marca agregada con éxito');
                } else {
                    alertify.alert('Mensaje', 'El nombre de la marca no puede estar vacío');
                }
            },
            function () {
                alertify.error('Operación cancelada');
            }
        ).set({ labels: { ok: 'Guardar', cancel: 'Cancelar' } });
    };

    const hanldeAddTalla = () => {
        alertify.prompt(
            'Agregar Talla',
            'Ingrese el nombre de la nueva talla:',
            '',
            function (evt, value) {
                if (value.trim() !== '') {
                    setFormData({ ...formData, talla: value });
                    setTallas([...talla, { id: talla.length + 1, talla: value }]);
                    alertify.alert('Mensaje', 'Talla agregada con éxito');
                } else {
                    alertify.alert('Mensaje', 'El nombre de la talla no puede estar vacío');
                }
            },
            function () {
                alertify.error('Operación cancelada');
            }
        ).set({ labels: { ok: 'Guardar', cancel: 'Cancelar' } });
    };

    return (
        <div>
            {loading ? <Loading /> : null}
            <CompanyMenu className="nav-menu" />
            <div className="body-zapatos">
                <h2>Crear Nuevo Zapato</h2>
                <form className="form-zapatos" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Color:</label>
                        <select
                            name="color"
                            value={formData.color}
                            onChange={handleChange}
                        >
                            <option value="">Seleccione un color</option>
                            {colores.map((color) => (
                                <option key={color.id} value={color.color}>
                                    {color.color}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="form-group">
                        <label>Talla:</label>
                        <div className='grupor-flex'>
                            <select
                                name="talla"
                                value={formData.talla}
                                onChange={handleChange}
                            >
                                <option value="">Seleccione una talla</option>
                                {talla.map((t) => (
                                    <option key={t.id} value={t.talla}>
                                        {t.talla}
                                    </option>
                                ))}
                            </select>
                            <label className='btn-mas' onClick={hanldeAddTalla} title='Agregar una nueva talla'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Costo:</label>
                        <input
                            type="number"
                            name="costo"
                            value={formData.costo}
                            onChange={handleChange}
                        />
                    </div>
                    <div className="form-group">
                        <label>Marca:</label>
                        <div className='grupor-flex'>
                            <select
                                name="marca"
                                value={formData.marca}
                                onChange={handleChange}
                            >
                                <option value="">Seleccione una marca</option>
                                {marca.map((m) => (
                                    <option key={m.id} value={m.marca}>
                                        {m.marca}
                                    </option>
                                ))}
                            </select>
                            <label className='btn-mas' onClick={hanldeAddMarca} title='Agregar una nueva marca'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Modelo:</label>
                        <input
                            type="text"
                            name="modelo"
                            value={formData.modelo}
                            onChange={handleChange}
                        />
                    </div>
                    <div className="form-group">
                        <label>Calidad:</label>
                        <select
                            name="calidad"
                            value={formData.calidad}
                            onChange={handleChange}
                        >
                            <option value="">Seleccione</option>
                            <option value="AA">AA</option>
                            <option value="AAA">AAA</option>
                            <option value="Tipo Original">Tipo Original</option>
                            <option value="Original">Original</option>
                        </select>
                    </div>
                    <div className="form-group form-group-textarea">
                        <label>Descripción:</label>
                        <textarea
                            name="descripcion"
                            value={formData.descripcion}
                            onChange={handleChange}
                        ></textarea>
                    </div>
                    <div className="form-group">
                        <label>Subir Imagen:</label>
                        <input
                            type="file"
                            accept="image/*"
                            onChange={handleFileChange}
                        />
                    </div>
                    {formData.url && (
                        <div className="form-group">
                            <label>Vista Previa:</label>
                            <img src={formData.url} alt="Vista previa" className="img-preview" />
                        </div>
                    )}
                    <button type="submit">Guardar Zapato</button>
                </form>
            </div>
        </div>
    );
};

export default CompanyZapatos;
